create or replace function public.has_tenant_permission(target uuid, permission_name text) returns boolean language sql stable security definer set search_path=public as $$
 select public.is_master_admin() or exists(select 1 from public.memberships m join public.tenants t on t.id=m.tenant_id where m.user_id=auth.uid() and m.tenant_id=target and m.active and t.state='approved' and (m.role='tenant_admin' or (m.role='employee' and (m.permissions->>'all'='true' or m.permissions->>permission_name='true'))));
$$;
revoke all on function public.has_tenant_permission(uuid,text) from public;
grant execute on function public.has_tenant_permission(uuid,text) to authenticated;
drop policy if exists client_read on public.clients;
create policy client_read on public.clients for select to authenticated using(public.has_tenant_permission(tenant_id,'clients.read') or exists(select 1 from public.collector_assignments ca where ca.tenant_id=clients.tenant_id and ca.client_id=clients.id and ca.collector_user_id=auth.uid() and ca.active));
drop policy if exists client_write on public.clients;
create policy client_write on public.clients for all to authenticated using(public.has_tenant_permission(tenant_id,'clients.write')) with check(public.has_tenant_permission(tenant_id,'clients.write'));
do $$ declare tab text; perm text; begin foreach tab in array array['client_documents','loans','loan_versions','installments','payments','payment_allocations','ledger_movements','expenses','daily_closures'] loop
 perm:=case when tab='client_documents' then 'documents.read' when tab in ('loans','loan_versions') then 'loans.read' when tab='installments' then 'installments.read' when tab in ('payments','payment_allocations') then 'payments.read' when tab='ledger_movements' then 'cash.read' when tab='expenses' then 'expenses.read' else 'cash.read' end;
 execute format('drop policy if exists tenant_select on public.%I',tab);
 execute format('create policy tenant_select on public.%I for select to authenticated using(public.has_tenant_permission(tenant_id,%L))',tab,perm);
end loop; end $$;
create or replace function public.create_loan_atomic(p jsonb) returns uuid language plpgsql security definer set search_path=public as $$
declare v_tenant uuid:=(p->>'tenant_id')::uuid; v_client uuid:=(p->>'client_id')::uuid; v_loan uuid:=gen_random_uuid(); v_user uuid:=auth.uid(); v_principal numeric(14,2):=(p->>'principal')::numeric; v_interest numeric(14,2):=(p->>'interest_amount')::numeric; v_total numeric(14,2):=(p->>'total_amount')::numeric; v_count int:=jsonb_array_length(p->'installments'); v_sum numeric(14,2); v_row jsonb; v_i int:=0;
begin
 if v_user is null or not public.has_tenant_permission(v_tenant,'loans.create') then raise exception 'not_authorized' using errcode='42501';end if;
 if v_principal<=0 or v_interest<0 or v_total<>v_principal+v_interest or v_count<1 then raise exception 'invalid_terms' using errcode='22023';end if;
 if not exists(select 1 from public.clients where id=v_client and tenant_id=v_tenant and active) then raise exception 'client_not_found' using errcode='22023';end if;
 select coalesce(sum((x->>'amount')::numeric),0) into v_sum from jsonb_array_elements(p->'installments') x;if v_sum<>v_total then raise exception 'installment_total_mismatch' using errcode='22023';end if;
 insert into public.loans(id,tenant_id,client_id,contract_number,modality,state,principal,interest_percent,interest_amount,total_amount,installment_count,installment_amount,start_date,due_day,late_fee,late_fee_block_days,include_sundays,terms_snapshot,created_by) values(v_loan,v_tenant,v_client,p->>'contract_number',(p->>'modality')::public.loan_modality,'active',v_principal,(p->>'interest_percent')::numeric,v_interest,v_total,v_count,v_total/v_count,(p->>'start_date')::date,nullif(p->>'due_day','')::int,coalesce((p->>'late_fee')::numeric,0),coalesce((p->>'late_fee_block_days')::int,2),coalesce((p->>'include_sundays')::boolean,true),p->'terms_snapshot',v_user);
 for v_row in select value from jsonb_array_elements(p->'installments') loop v_i:=v_i+1;insert into public.installments(tenant_id,loan_id,sequence,due_date,amount) values(v_tenant,v_loan,v_i,(v_row->>'due_date')::date,(v_row->>'amount')::numeric);end loop;
 insert into public.ledger_movements(tenant_id,kind,amount,direction,occurred_at,reference_table,reference_id,description,idempotency_key,created_by) values(v_tenant,'loan_disbursement',v_principal,-1,((p->>'start_date')::date::timestamp at time zone 'America/Sao_Paulo'),'loans',v_loan,'Liberação do contrato '||(p->>'contract_number'),'loan:'||v_loan::text,v_user);
 insert into public.audit_log(tenant_id,actor_id,action,entity,entity_id,metadata) values(v_tenant,v_user,'loan.created','loans',v_loan,jsonb_build_object('principal',v_principal,'installments',v_count));return v_loan;
end $$;
create or replace function public.record_payment_atomic(p_tenant uuid,p_loan uuid,p_amount numeric,p_paid_at timestamptz,p_idempotency_key text,p_note text default null) returns uuid language plpgsql security definer set search_path=public as $$
declare v_user uuid:=auth.uid(); v_payment uuid; v_left numeric(14,2):=round(p_amount,2); v_due numeric(14,2); v_alloc numeric(14,2); v_row record;
begin
 if v_user is null or not public.has_tenant_permission(p_tenant,'payments.receive') then raise exception 'not_authorized' using errcode='42501';end if;
 if p_amount<=0 or p_idempotency_key is null or length(p_idempotency_key)>120 then raise exception 'invalid_payment' using errcode='22023';end if;
 select id into v_payment from public.payments where tenant_id=p_tenant and idempotency_key=p_idempotency_key;if v_payment is not null then return v_payment;end if;
 perform 1 from public.loans where id=p_loan and tenant_id=p_tenant and state='active' for update;if not found then raise exception 'loan_not_active' using errcode='22023';end if;
 select coalesce(sum(amount-paid_amount),0) into v_due from public.installments where tenant_id=p_tenant and loan_id=p_loan and state in ('open','partial');if round(p_amount,2)>v_due then raise exception 'payment_exceeds_balance' using errcode='22023';end if;
 insert into public.payments(tenant_id,loan_id,amount,paid_at,note,received_by,idempotency_key) values(p_tenant,p_loan,round(p_amount,2),p_paid_at,p_note,v_user,p_idempotency_key) returning id into v_payment;
 for v_row in select id,amount,paid_amount from public.installments where tenant_id=p_tenant and loan_id=p_loan and state in ('open','partial') order by due_date,sequence for update loop exit when v_left<=0;v_alloc:=least(v_left,v_row.amount-v_row.paid_amount);insert into public.payment_allocations(tenant_id,payment_id,installment_id,amount) values(p_tenant,v_payment,v_row.id,v_alloc);update public.installments set paid_amount=paid_amount+v_alloc,state=case when paid_amount+v_alloc>=amount then 'paid'::public.installment_state else 'partial'::public.installment_state end where id=v_row.id;v_left:=v_left-v_alloc;end loop;
 insert into public.ledger_movements(tenant_id,kind,amount,direction,occurred_at,reference_table,reference_id,description,idempotency_key,created_by) values(p_tenant,'payment',round(p_amount,2),1,p_paid_at,'payments',v_payment,'Recebimento de parcela','payment:'||v_payment::text,v_user);
 if not exists(select 1 from public.installments where tenant_id=p_tenant and loan_id=p_loan and state in ('open','partial')) then update public.loans set state='paid',updated_at=now() where id=p_loan;end if;
 insert into public.audit_log(tenant_id,actor_id,action,entity,entity_id,metadata) values(p_tenant,v_user,'payment.recorded','payments',v_payment,jsonb_build_object('amount',round(p_amount,2),'loan_id',p_loan));return v_payment;
end $$;
create or replace function public.create_expense_atomic(p_tenant uuid,p_category text,p_amount numeric,p_date date,p_note text default null) returns uuid language plpgsql security definer set search_path=public as $$
declare v_user uuid:=auth.uid();v_expense uuid:=gen_random_uuid();v_move uuid:=gen_random_uuid();begin if v_user is null or not public.has_tenant_permission(p_tenant,'expenses.create') then raise exception 'not_authorized' using errcode='42501';end if;if length(trim(p_category))<2 or length(p_category)>100 or p_amount<=0 then raise exception 'invalid_expense' using errcode='22023';end if;insert into public.ledger_movements(id,tenant_id,kind,amount,direction,occurred_at,reference_table,reference_id,description,idempotency_key,created_by) values(v_move,p_tenant,'expense',round(p_amount,2),-1,(p_date::timestamp at time zone 'America/Sao_Paulo'),'expenses',v_expense,'Despesa: '||trim(p_category),'expense:'||v_expense::text,v_user);insert into public.expenses(id,tenant_id,category,amount,expense_date,note,ledger_movement_id,created_by) values(v_expense,p_tenant,trim(p_category),round(p_amount,2),p_date,p_note,v_move,v_user);insert into public.audit_log(tenant_id,actor_id,action,entity,entity_id) values(p_tenant,v_user,'expense.created','expenses',v_expense);return v_expense;end $$;
create or replace function public.dashboard_summary(p_tenant uuid) returns jsonb language plpgsql security invoker set search_path=public as $$ declare v_today date:=(now() at time zone 'America/Sao_Paulo')::date;v_month date:=date_trunc('month',now() at time zone 'America/Sao_Paulo')::date;v_out jsonb;begin if not public.has_tenant_permission(p_tenant,'dashboard.read') then raise exception 'not_authorized' using errcode='42501';end if;select jsonb_build_object('asOf',v_today,'clients',(select count(*) from public.clients c where c.tenant_id=p_tenant and c.active),'activeLoans',(select count(*) from public.loans l where l.tenant_id=p_tenant and l.state='active'),'principalActive',(select coalesce(sum(l.principal),0) from public.loans l where l.tenant_id=p_tenant and l.state='active'),'receivable',(select coalesce(sum(i.amount-i.paid_amount),0) from public.installments i where i.tenant_id=p_tenant and i.state in ('open','partial')),'cashBalance',(select coalesce(sum(m.amount*m.direction),0) from public.ledger_movements m where m.tenant_id=p_tenant),'cashInMonth',(select coalesce(sum(m.amount),0) from public.ledger_movements m where m.tenant_id=p_tenant and m.direction=1 and m.kind='payment' and (m.occurred_at at time zone 'America/Sao_Paulo')::date>=v_month),'cashOutMonth',(select coalesce(sum(m.amount),0) from public.ledger_movements m where m.tenant_id=p_tenant and m.direction=-1 and (m.occurred_at at time zone 'America/Sao_Paulo')::date>=v_month),'dueToday',(select coalesce(sum(i.amount-i.paid_amount),0) from public.installments i where i.tenant_id=p_tenant and i.due_date=v_today and i.state in ('open','partial')),'dueCount',(select count(*) from public.installments i where i.tenant_id=p_tenant and i.due_date=v_today and i.state in ('open','partial')),'overdue',(select coalesce(sum(i.amount-i.paid_amount),0) from public.installments i where i.tenant_id=p_tenant and i.due_date<v_today and i.state in ('open','partial')),'overdueCount',(select count(*) from public.installments i where i.tenant_id=p_tenant and i.due_date<v_today and i.state in ('open','partial'))) into v_out;return v_out;end $$;
drop policy if exists assignment_manage on public.collector_assignments;
create policy assignment_manage on public.collector_assignments for all to authenticated using(public.has_tenant_permission(tenant_id,'routes.assign')) with check(public.has_tenant_permission(tenant_id,'routes.assign'));
drop policy if exists visit_insert on public.collector_visits;
create policy visit_insert on public.collector_visits for insert to authenticated with check(
 public.has_tenant_permission(tenant_id,'routes.visit') or
 (collector_user_id=auth.uid() and public.has_tenant_role(tenant_id,array['collector']::public.member_role[]) and exists(select 1 from public.collector_assignments ca where ca.tenant_id=collector_visits.tenant_id and ca.client_id=collector_visits.client_id and ca.collector_user_id=auth.uid() and ca.active))
);
