 insert into public.ledger_movements(tenant_id,kind,amount,direction,occurred_at,reference_table,reference_id,description,idempotency_key,created_by) values(v_tenant,'loan_disbursement',v_principal,-1,((p->>'start_date')::date::timestamp at time zone 'America/Sao_Paulo'),'loans',v_loan,'Liberação do contrato '||(p->>'contract_number'),'loan:'||v_loan::text,v_user);insert into public.audit_log(tenant_id,actor_id,action,entity,entity_id,metadata) values(v_tenant,v_user,'loan.created','loans',v_loan,jsonb_build_object('principal',v_principal,'installments',v_count));return v_loan;end $$;
create or replace function public.record_payment_atomic(p_tenant uuid,p_loan uuid,p_amount numeric,p_paid_at timestamptz,p_idempotency_key text,p_note text default null) returns uuid language plpgsql security definer set search_path=public as $$
declare v_user uuid:=auth.uid();v_payment uuid;v_left numeric(14,2):=round(p_amount,2);v_due numeric(14,2);v_alloc numeric(14,2);v_row record;begin
 if v_user is null or not public.has_tenant_permission(p_tenant,'payments.receive') then raise exception 'not_authorized' using errcode='42501';end if;if p_amount<=0 or p_idempotency_key is null or length(p_idempotency_key)>120 then raise exception 'invalid_payment' using errcode='22023';end if;select id into v_payment from public.payments where tenant_id=p_tenant and idempotency_key=p_idempotency_key;if v_payment is not null then return v_payment;end if;perform 1 from public.loans where id=p_loan and tenant_id=p_tenant and state='active' for update;if not found then raise exception 'loan_not_active' using errcode='22023';end if;select coalesce(sum(amount-paid_amount),0) into v_due from public.installments where tenant_id=p_tenant and loan_id=p_loan and state in ('open','partial');if round(p_amount,2)>v_due then raise exception 'payment_exceeds_balance' using errcode='22023';end if;insert into public.payments(tenant_id,loan_id,amount,paid_at,note,received_by,idempotency_key) values(p_tenant,p_loan,round(p_amount,2),p_paid_at,p_note,v_user,p_idempotency_key) returning id into v_payment;for v_row in select id,amount,paid_amount from public.installments where tenant_id=p_tenant and loan_id=p_loan and state in ('open','partial') order by due_date,sequence for update loop exit when v_left<=0;v_alloc:=least(v_left,v_row.amount-v_row.paid_amount);insert into public.payment_allocations(tenant_id,payment_id,installment_id,amount) values(p_tenant,v_payment,v_row.id,v_alloc);update public.installments set paid_amount=paid_amount+v_alloc,state=case when paid_amount+v_alloc>=amount then 'paid'::public.installment_state else 'partial'::public.installment_state end where id=v_row.id;v_left:=v_left-v_alloc;end loop;insert into public.ledger_movements(tenant_id,kind,amount,direction,occurred_at,reference_table,reference_id,description,idempotency_key,created_by) values(p_tenant,'payment',round(p_amount,2),1,p_paid_at,'payments',v_payment,'Recebimento de parcela','payment:'||v_payment::text,v_user);if not exists(select 1 from public.installments where tenant_id=p_tenant and loan_id=p_loan and state in ('open','partial')) then update public.loans set state='paid',updated_at=now() where id=p_loan;end if;insert into public.audit_log(tenant_id,actor_id,action,entity,entity_id,metadata) values(p_tenant,v_user,'payment.recorded','payments',v_payment,jsonb_build_object('amount',round(p_amount,2),'loan_id',p_loan));return v_payment;end $$;
drop policy if exists assignment_read on public.collector_assignments;
create policy assignment_read on public.collector_assignments for select to authenticated using(public.has_tenant_permission(tenant_id,'routes.read') or (collector_user_id=auth.uid() and active and public.is_tenant_member(tenant_id)));
drop policy if exists visit_read on public.collector_visits;
create policy visit_read on public.collector_visits for select to authenticated using(public.has_tenant_permission(tenant_id,'routes.read') or (collector_user_id=auth.uid() and public.is_tenant_member(tenant_id)));
drop policy if exists client_document_insert on public.client_documents;
create policy client_document_insert on public.client_documents for insert to authenticated with check(public.has_tenant_permission(tenant_id,'documents.upload'));
